#!/usr/bin/env bash
set -euo pipefail

jsonschema=(npx --yes @sourcemeta/jsonschema@17.0.0)

git -C "$PROJECT_ROOT" ls-files -z '*.sh' | xargs -0 -I{} shellcheck "$PROJECT_ROOT/{}"
shellcheck "$PROJECT_ROOT/.githooks/pre-push"
shasum --algorithm 256 --check --strict --quiet "$PROJECT_ROOT/guardrails.sha256"
jq --compact-output --sort-keys "{scripts, allowScripts}" "$PROJECT_ROOT/tools/pr-review/package.json" | shasum --algorithm 256 --check --strict --quiet "$PROJECT_ROOT/tools/pr-review/package-scripts.sha256"
semgrep --test --metrics=off "$PROJECT_ROOT/semgrep"
test "$(grep --only-matching --no-filename 'notYetImplemented[A-Za-z]*' "$PROJECT_ROOT"/tools/pr-review/src/client/*/review-tool*.ts | wc -l)" -le "$(cat "$PROJECT_ROOT/tools/pr-review/not-yet-implemented.count")"
test "$(git -C "$PROJECT_ROOT" ls-files 'tools/pr-review/scripts/*.ts' | wc -l)" -le "$(cat "$PROJECT_ROOT/tools/pr-review/ceilings/hand-written-generators.count")"
test "$(git -C "$PROJECT_ROOT" ls-files -z 'tools/pr-review/src/domain/*.ts' 'tools/pr-review/src/controller/*.ts' | xargs -0 awk 'FNR == 1 { seen = 0 } FILENAME ~ /\.test(-support)?\.ts$/ { next } /from "zod"/ && !seen { files++; seen = 1 } END { print files + 0 }')" -le "$(cat "$PROJECT_ROOT/tools/pr-review/ceilings/files-with-zod-in-domain-and-controller.count")"
test "$(git -C "$PROJECT_ROOT" ls-files -z 'tools/pr-review/src/*.ts' 'tools/pr-review/scripts/*.ts' | xargs -0 awk '/JSON\.(parse|stringify)/ { lines++ } END { print lines + 0 }')" -le "$(cat "$PROJECT_ROOT/tools/pr-review/ceilings/lines-with-json-parse-or-stringify.count")"

"$PROJECT_ROOT/scripts/declared-ids.schema.sh" > "$PROJECT_ROOT/schemas/governance/declared-ids.g.schema.json"
"${jsonschema[@]}" lint "$PROJECT_ROOT/schemas" --resolve "$PROJECT_ROOT/schemas"
"${jsonschema[@]}" metaschema "$PROJECT_ROOT/schemas" --resolve "$PROJECT_ROOT/schemas"
"${jsonschema[@]}" validate "$PROJECT_ROOT/schemas/governance/declared-ids.g.schema.json" "$PROJECT_ROOT/rules" --resolve "$PROJECT_ROOT/schemas"
"${jsonschema[@]}" validate "$PROJECT_ROOT/schemas/governance/rules.schema.json" "$PROJECT_ROOT/skills/pr-review/rules/Rules.yaml" --resolve "$PROJECT_ROOT/schemas"
"${jsonschema[@]}" validate "$PROJECT_ROOT/schemas/governance/principles.schema.json" "$PROJECT_ROOT/skills/pr-review/rules/Principles.yaml" --resolve "$PROJECT_ROOT/schemas"
"${jsonschema[@]}" validate "$PROJECT_ROOT/schemas/governance/definitions.schema.json" "$PROJECT_ROOT/skills/pr-review/rules/Definitions.yaml" --resolve "$PROJECT_ROOT/schemas"

npm --prefix "$PROJECT_ROOT/tools/pr-review" ci --no-audit --no-fund
npm --prefix "$PROJECT_ROOT/tools/pr-review" run verify
test "$(find "$PROJECT_ROOT/tools/pr-review/src/generated" -name '*.g.ts' -print0 | xargs -0 awk 'FNR == 1 { files++ } /Generated by orval/ { by_orval++ } END { print files - by_orval }')" -le "$(cat "$PROJECT_ROOT/tools/pr-review/ceilings/generated-files-not-by-orval.count")"
npx --yes @agentplugins/cli@0.6.1 audit "$PROJECT_ROOT"

"$PROJECT_ROOT/skills/pr-review/dist/bin/review-tool.mjs" -h
"$PROJECT_ROOT/skills/pr-review/dist/bin/review-tool-probe.mjs" -h
